<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {AlertCircle,LoaderCircle,ChevronLeft,ChevronRight,Database,Info,Search} from 'lucide-vue-next';
type Item=Record<string,any>;
const props=defineProps<{report:Item;schema:string;busy:boolean;error?:string}>();
const emit=defineEmits<{query:[filters:{schema:string|null;search:string|null;offset:number}]}>();
const search=ref(props.report.search??'');const localSearch=ref('');const tableLimit=ref(20);const columnLimits=ref<Record<string,number>>({});
const tables=computed<Item[]>(()=>props.report.tables??[]);
const filtered=computed(()=>tables.value.filter(table=>(`${table.schema??''}.${table.name} `+table.columns.map((column:Item)=>column.name).join(' ')).toLowerCase().includes(localSearch.value.toLowerCase())));
const visible=computed(()=>filtered.value.slice(0,tableLimit.value));
function key(table:Item){return JSON.stringify([table.schema,table.name]);}
function columns(table:Item){return table.columns.slice(0,columnLimits.value[key(table)]??25);}
function moreColumns(table:Item){if(!props.busy)columnLimits.value[key(table)]=(columnLimits.value[key(table)]??25)+50;}
function filter(){if(!props.busy)emit('query',{schema:props.schema.trim()||null,search:search.value.trim()||null,offset:0});}
function page(offset:number){if(!props.busy)emit('query',{schema:props.report.schema??null,search:props.report.search??null,offset});}
watch(()=>props.report,()=>{search.value=props.report.search??'';localSearch.value='';tableLimit.value=20;columnLimits.value={};});
</script>
<template>
 <section class="source-schema" :aria-busy="busy" aria-label="Tabelas e colunas da fonte" data-tour="credential-schema">
  <div class="schema-guidance"><Info :size="17"/><div><p>Explore os campos disponíveis para esta conexão. Nenhum registro de negócio é consultado.</p><details><summary>Como interpretar esta estrutura</summary><p>{{report.scope_warning||'Esta estrutura foi fornecida pelo conector. A visibilidade depende das permissões da conexão e dos limites indicados. Ela não comprova acesso aos registros.'}}</p></details></div></div>
  <form v-if="report.search_supported" class="schema-search" @submit.prevent="filter"><label>Buscar por tabela ou coluna<div><Search :size="16"/><input v-model="search" maxlength="100" :disabled="busy" placeholder="Ex.: financeiro, unidade, latitude…"></div></label><button type="submit" class="secondary-button" :disabled="busy">Buscar na fonte</button></form>
  <label v-else class="schema-local-search"><Search :size="15"/><input v-model="localSearch" :disabled="busy" aria-label="Filtrar tabelas ou colunas deste resultado" placeholder="Filtrar este resultado…"></label>
  <p v-if="busy" class="query-status" role="status"><LoaderCircle :size="15" class="spin"/>Consultando a fonte… O resultado anterior continua visível até a resposta.</p>
  <p v-if="error" class="form-error query-error" role="alert"><AlertCircle :size="16"/>{{error}}</p>
  <p class="schema-scope">{{report.schema?'Schema consultado: '+report.schema:'Estrutura disponível para a conexão'}}<span v-if="report.search"> · Busca: {{report.search}}</span></p>
  <nav v-if="report.pagination_supported&&(report.offset>0||report.next_offset!=null)" class="schema-pagination" aria-label="Páginas da estrutura"><button type="button" class="secondary-button" :disabled="busy||report.offset===0" @click="page(Math.max(0,report.offset-report.page_size))"><ChevronLeft :size="15"/>Anterior</button><span>Página {{Math.floor(report.offset/report.page_size)+1}}</span><button type="button" class="secondary-button" :disabled="busy||report.next_offset==null" @click="page(report.next_offset)">Próxima<ChevronRight :size="15"/></button></nav>
  <p class="schema-scope">{{filtered.length?'Exibindo '+visible.length+' de '+filtered.length+' tabelas deste resultado.':tables.length?'Nenhuma tabela corresponde ao filtro local.':'Nenhuma tabela ou coluna ficou visível nesta consulta e nos filtros escolhidos.'}}</p>
  <details v-for="table in visible" :key="key(table)" class="schema-table"><summary><Database :size="16"/><div><strong>{{table.name}}</strong><small>{{table.schema||'Schema não informado'}} · {{table.visible_column_count?table.columns.length+' de '+table.visible_column_count+' campos visíveis':table.columns.length+' campos retornados'}}</small></div><span v-if="table.columns_complete===false||table.columns_truncated" class="schema-partial">Campos parciais</span></summary><div class="schema-fields"><p v-if="table.columns_complete===false" class="schema-warning">Esta página contém parte dos campos visíveis da tabela. Continue pelas páginas ou refine a busca pelo nome da tabela para conferir o restante.</p><p v-else-if="table.columns_truncated" class="schema-warning">A lista de campos foi limitada. Use o filtro de schema ou investigue a fonte com as operações disponíveis para este conector.</p><dl><div v-for="(column,index) in columns(table)" :key="index"><dt>{{column.name}}</dt><dd>{{column.type||'Tipo não informado'}}</dd></div></dl><button v-if="columns(table).length<table.columns.length" type="button" class="text-button schema-more" :disabled="busy" @click="moreColumns(table)">Mostrar mais campos · {{table.columns.length-columns(table).length}} restantes neste resultado</button></div></details>
  <button v-if="filtered.length>visible.length" type="button" class="text-button schema-more" :disabled="busy" @click="tableLimit+=20">Mostrar mais tabelas deste resultado · {{filtered.length-visible.length}} restantes</button>
  <p v-if="report.truncated" class="schema-warning">{{report.pagination_limit_reached?'O limite de paginação foi atingido. Refine a busca para continuar.':report.pagination_supported?'Há mais campos na fonte. Continue pelas páginas ou refine a busca; uma tabela pode continuar na próxima página.':'O resultado deste conector foi limitado e não oferece paginação remota. Use o filtro de schema para reduzir a consulta; a lista não comprova toda a estrutura da fonte.'}}</p>
 </section>
</template>
<style scoped>
.query-status{display:flex;gap:8px;align-items:flex-start;font-size:11px;line-height:1.8;color:#466a9b;margin:12px 0}.query-status svg,.query-error svg{flex-shrink:0;margin-top:2px}.query-error{margin:12px 0;font-size:12px;line-height:1.8}
.source-schema{margin-top:16px}.schema-guidance{display:flex;gap:9px;padding:12px;background:#edf4ff;border:1px solid #d9e6fa;border-radius:8px;color:#45658e}.schema-guidance>svg{flex-shrink:0;margin-top:2px}.schema-guidance>div{min-width:0}.schema-guidance p{font-size:12px;line-height:1.8;margin:0}.schema-guidance details{margin-top:6px}.schema-guidance details p{margin-top:8px}.schema-guidance summary{font-size:11px;color:#35649f;cursor:pointer;line-height:1.7}.schema-search{display:flex;gap:10px;align-items:flex-end;margin:16px 0 8px}.schema-search label{flex:1;min-width:0;font-size:11px;color:#425f83}.schema-search label>div,.schema-local-search{display:flex;gap:8px;align-items:center;border:1px solid #dbe5f3;background:#fff;border-radius:7px;padding:0 10px;margin-top:6px;color:#6e88ab}.schema-search input,.schema-local-search input{min-width:0;width:100%;border:0;box-shadow:none;background:transparent;margin:0}.schema-local-search{margin-top:16px}.schema-search button{min-height:41px;font-size:11px}.schema-scope{font-size:11px;line-height:1.8;color:#647c9c;margin:10px 0}.schema-pagination{display:flex;gap:10px;justify-content:space-between;align-items:center;margin:15px 0}.schema-pagination span{font-size:11px;color:#5d7495}.schema-pagination button{font-size:11px}.schema-table{border:1px solid #dbe5f2;border-radius:8px;background:white;margin-top:10px;min-width:0}.schema-table>summary{display:flex;gap:9px;align-items:center;cursor:pointer;padding:13px;color:#426997}.schema-table>summary>svg{flex-shrink:0}.schema-table>summary>div{min-width:0}.schema-table strong{display:block;font-size:12px;overflow-wrap:anywhere}.schema-table small{display:block;font-size:10px;color:#6b819e;margin-top:5px;line-height:1.7;overflow-wrap:anywhere}.schema-partial{font-size:10px;padding:4px 7px;border-radius:5px;color:#8b5a20;background:#fff3df;margin-left:auto;flex-shrink:0}.schema-fields{padding:0 13px 12px}.schema-fields dl{margin:0}.schema-fields dl>div{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;padding:8px 0;border-top:1px solid #e7eef8}.schema-fields dt,.schema-fields dd{font-size:11px;line-height:1.7;color:#466385;margin:0;overflow-wrap:anywhere}.schema-fields dd{color:#7486a0}.schema-warning{font-size:11px;line-height:1.8;color:#8a5d29;margin:12px 0}.schema-more{font-size:11px;margin-top:12px}.source-schema button:focus-visible{outline:2px solid #0861ee;outline-offset:3px}@media(max-width:600px){.schema-search{align-items:stretch;flex-direction:column}.schema-search button{align-self:flex-end}.schema-table>summary{flex-wrap:wrap;padding:11px}.schema-partial{margin-left:24px}.schema-fields{padding:0 11px 11px}}
</style>
